/* 1. IMPORT STYLISH FONTS */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Montserrat:wght@400;600&display=swap');

/* === SHARED HERO SETTINGS === 
   Ensures outer width, height, and borders match across sections */
.hero-freedom-series-wear-your-boldness,
.hero-stylish-hoodies-t-shirts {
    background-size: cover !important;
    background-position: center top !important; /* Keeps heads visible at top */
    min-height: 650px !important; 
    display: flex !important;
    align-items: flex-end !important; /* Anchors the overlay to the bottom */
    justify-content: center !important;

    /* ADJUST THIS VALUE: 
       Increasing this moves the overlay HIGHER (toward the bust)
       Decreasing this moves it LOWER (toward the waist) */
    padding-bottom: 120px !important; 

    margin: 10px auto !important;
    max-width: 98% !important;

    /* Consistency Frame */
    border: 3px solid rgba(255, 255, 255, 0.4) !important;
    border-radius: 20px !important;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4) !important;
    overflow: hidden !important;
}

/* === SHARED HERO CONTENT BOX (The Overlay) === */
.hero-freedom-series-wear-your-boldness .hero-content,
.hero-stylish-hoodies-t-shirts .hero-content {
    /* WIDE WIDTH: Ensures "T-Shirts" stays on one line */
    max-width: 1000px !important; 
    width: 95% !important;

    /* SLIM HEIGHT: Minimal internal padding */
    padding: 10px 40px !important; 

    /* Transparency & Glass Effect */
    background: rgba(0, 0, 0, 0.25) !important; 
    backdrop-filter: blur(5px) !important;
    -webkit-backdrop-filter: blur(5px) !important;
    text-align: center !important;
    border-radius: 12px !important;
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
}

/* === HEADLINE STYLING === */
.hero-content h1 {
    font-family: 'Playfair Display', serif !important;
    color: white !important;
    font-size: 3.5rem !important; /* Slightly smaller to help fit one line */
    font-weight: 900 !important;
    line-height: 1.1 !important;
    margin-bottom: 5px !important; /* Tight spacing for low height */
    text-shadow: 0px 4px 15px rgba(0, 0, 0, 0.4) !important; 
}

/* === SUBTEXT STYLING === */
.hero-content p {
    font-family: 'Montserrat', sans-serif !important;
    color: #f8f8f8 !important;
    font-size: 1rem !important;
    text-transform: uppercase !important;
    letter-spacing: 3px !important;
    margin-bottom: 15px !important; /* Tight spacing for low height */
}

/* === BUTTON STYLING === */
.hero-content .btn {
    font-family: 'Montserrat', sans-serif !important;
    padding: 12px 35px !important; 
    font-weight: 600 !important;
    text-transform: uppercase !important;
    border-radius: 4px !important;
    transition: all 0.3s ease !important;
    display: inline-block !important;
    text-decoration: none !important;
}

/* Brand Specific Colors */
.hero-freedom-series-wear-your-boldness .hero-content .btn {
    background: #ff3366 !important;
    color: white !important;
}

.hero-stylish-hoodies-t-shirts .hero-content .btn {
    background: #ffffff !important;
    color: #000000 !important;
}

/* === MOBILE RESPONSIVENESS === */
@media (max-width: 768px) {
    .hero-content {
        max-width: 95% !important;
        padding: 15px 20px !important;
    }
    .hero-content h1 {
        font-size: 2.2rem !important;
    }
}

